     8	
     9	/** Aritmética de dinheiro: sempre 2 casas, arredondamento meio-para-o-par a cada passo. */
    10	public final class Money {
    11	    public static final BigDecimal ZERO = new BigDecimal("0.00");
    12	
    13	    private Money() {}
    14	
    15	    public static BigDecimal round(BigDecimal value) {
    16	        return value.setScale(2, RoundingMode.HALF_EVEN);
    17	    }
    18	
    19	    public static BigDecimal of(String value) {
    20	        return round(new BigDecimal(value));
    21	    }
    22	
    23	    /** base * fator, arredondado. */
    24	    public static BigDecimal times(BigDecimal base, BigDecimal factor) {
    25	        return round(base.multiply(factor));
    26	    }
    27	
    28	    /** "R$ 1.234,56" */
    29	    public static String brl(BigDecimal value) {
    30	        DecimalFormatSymbols symbols = new DecimalFormatSymbols(Locale.ROOT);
    31	        symbols.setGroupingSeparator('.');
    32	        symbols.setDecimalSeparator(',');
    33	        return "R$ " + new DecimalFormat("#,##0.00", symbols).format(round(value));
    34	    }
    35	}
