    14	    public static String date(LocalDate d) {
    15	        return d.format(BR_DATE);
    16	    }
    17	
    18	    /** 11 dígitos viram 000.000.000-00; qualquer outra coisa fica como veio. */
    19	    public static String cpf(String raw) {
    20	        String digits = raw.replaceAll("\\D", "");
    21	        if (digits.length() != 11) return raw;
    22	        return digits.substring(0, 3) + "." + digits.substring(3, 6) + "." + digits.substring(6, 9) + "-" + digits.substring(9);
    23	    }
