    28	        sb.append("Hóspede: ").append(r.guestName()).append(" (CPF ").append(cpf(r.guestCpf())).append(")\n");
    29	        sb.append("Quarto: ").append(room.number()).append(" (").append(room.type()).append(")\n");
    30	        sb.append("Entrada: ").append(date(r.checkIn())).append(" | Saída: ").append(date(r.checkOut()))
    31	                .append(" | ").append(r.nights()).append(r.nights() == 1 ? " diária" : " diárias").append('\n');
    32	        sb.append("Diárias: ").append(Money.brl(r.subtotal())).append('\n');
    33	        if (r.discount().signum() > 0) {
    34	            sb.append("Desconto: ").append(Money.brl(r.discount())).append('\n');
    35	        }
    36	        sb.append("Total: ").append(Money.brl(r.total()));
    37	        return sb.toString();
    38	    }
