     7	
     8	/** Relatórios CSV de ocupação e financeiro. */
     9	public final class ReportService {
    10	    private final Db db;
    11	    private final Repository repo;
    12	
    13	    public ReportService(Db db, Repository repo) {
    14	        this.db = db;
    15	        this.repo = repo;
    16	    }
    17	
    18	    public String occupancy(LocalDate night) {
    19	        return db.tx(c -> {
    20	            List<Reservation> rows = repo.occupying(c, night);
    21	            List<Room> rooms = repo.rooms(c);
    22	            StringBuilder sb = new StringBuilder("room,type,reservation,check_in,check_out\n");
    23	            for (Reservation r : rows) {
    24	                Room room = rooms.stream().filter(x -> x.number() == r.roomNumber()).findFirst().orElseThrow();
    25	                sb.append(r.roomNumber()).append(',').append(room.type()).append(',').append(r.id()).append(',')
    26	                        .append(r.checkIn()).append(',').append(r.checkOut()).append('\n');
    27	            }
    28	            long occupied = rows.stream().map(Reservation::roomNumber).distinct().count();
    29	            sb.append("total,").append(occupied).append('/').append(rooms.size()).append('\n');
    30	            return sb.toString();
    31	        });
    32	    }
    33	
    34	    public String revenue(YearMonth month) {
    35	        return db.tx(c -> {
    36	            List<Reservation> rows = repo.revenue(c, month.atDay(1), month.plusMonths(1).atDay(1));
    37	            StringBuilder sb = new StringBuilder("reservation,room,check_in,check_out,status,amount\n");
    38	            BigDecimal sum = Money.ZERO;
    39	            for (Reservation r : rows) {
    40	                BigDecimal kept = r.amountPaid().subtract(r.refund() == null ? Money.ZERO : r.refund());
    41	                sum = sum.add(kept);
    42	                sb.append(r.id()).append(',').append(r.roomNumber()).append(',').append(r.checkIn()).append(',')
    43	                        .append(r.checkOut()).append(',').append(r.status()).append(',').append(kept.toPlainString()).append('\n');
    44	            }
    45	            sb.append("total,").append(sum.toPlainString()).append('\n');
    46	            return sb.toString();
    47	        });
    48	    }
    49	}
