    15	    // ---- quartos
    16	    public List<Room> rooms(Connection c) throws SQLException {
    17	        try (Statement s = c.createStatement(); ResultSet rs = s.executeQuery(
    18	                "SELECT number, type, capacity, nightly_rate FROM rooms ORDER BY number")) {
    19	            List<Room> out = new ArrayList<>();
    20	            while (rs.next()) out.add(room(rs));
    21	            return out;
