    40	    public boolean hasOverlap(Connection c, int roomNumber, LocalDate checkIn, LocalDate checkOut) throws SQLException {
    41	        try (PreparedStatement ps = c.prepareStatement(
    42	                "SELECT 1 FROM reservations WHERE room_number = ? AND status <> 'CANCELLED' AND check_in < ? AND ? < check_out LIMIT 1")) {
    43	            ps.setInt(1, roomNumber);
    44	            ps.setObject(2, checkOut);
    45	            ps.setObject(3, checkIn);
    46	            try (ResultSet rs = ps.executeQuery()) {
