    58	    private static ReservationService.CreateCommand parseCreate(String body) {
    59	        JsonNode root;
    60	        try {
    61	            root = JSON.readTree(body);
    62	        } catch (JsonProcessingException e) {
    63	            throw ApiException.invalid("O corpo não é um JSON válido.");
    64	        }
    65	        if (root == null || !root.isObject()) throw ApiException.invalid("O corpo deve ser um objeto JSON.");
    66	
    67	        String guestName = text(root, "guestName");
    68	        String guestEmail = text(root, "guestEmail");
    69	        String guestCpf = text(root, "guestCpf");
    70	        String ratePlan = text(root, "ratePlan");
    71	        LocalDate checkIn = date(root, "checkIn");
    72	        LocalDate checkOut = date(root, "checkOut");
    73	        JsonNode room = root.get("roomNumber");
    74	        if (room == null || !room.isIntegralNumber() || !room.canConvertToInt()) throw ApiException.invalid("roomNumber é obrigatório e deve ser inteiro.");
    75	        JsonNode guests = root.get("guests");
    76	        if (guests == null || !guests.isIntegralNumber() || !guests.canConvertToInt() || guests.asInt() < 1) {
    77	            throw ApiException.invalid("guests é obrigatório e deve ser um inteiro maior que zero.");
    78	        }
    79	        if (!checkOut.isAfter(checkIn)) throw ApiException.invalid("checkOut deve ser depois de checkIn.");
    80	        if (RatePlans.find(ratePlan).isEmpty()) throw ApiException.invalid("ratePlan desconhecido: " + ratePlan);
    81	
    82	        JsonNode company = root.get("companyCode");
    83	        String companyCode = company != null && company.isTextual() ? company.asText() : null;
    84	        return new ReservationService.CreateCommand(room.asInt(), guestName, guestEmail, guestCpf, checkIn, checkOut,
    85	                guests.asInt(), ratePlan, companyCode);
    86	    }
