     1	package br.com.marealta.plan;
     2	
     3	import br.com.marealta.Money;
     4	import br.com.marealta.Room;
     5	
     6	import java.math.BigDecimal;
     7	import java.time.LocalDate;
     8	import java.time.temporal.ChronoUnit;
     9	
    10	/** Tudo que um plano pode precisar para precificar uma reserva. */
    11	public record PricingContext(Room room, LocalDate checkIn, LocalDate checkOut, String companyCode) {
    12	    private static final BigDecimal HIGH_SEASON_FACTOR = new BigDecimal("1.20");
    13	
    14	    public int nights() {
    15	        return (int) ChronoUnit.DAYS.between(checkIn, checkOut);
    16	    }
    17	
    18	    /** Alta temporada: de 15/12 ao fim de fevereiro e todo julho. */
    19	    public static boolean isHighSeason(LocalDate night) {
    20	        int month = night.getMonthValue();
    21	        return month == 1 || month == 2 || month == 7 || (month == 12 && night.getDayOfMonth() >= 15);
    22	    }
    23	
    24	    public BigDecimal nightPrice(LocalDate night) {
    25	        BigDecimal rate = room.nightlyRate();
    26	        return isHighSeason(night) ? Money.times(rate, HIGH_SEASON_FACTOR) : Money.round(rate);
    27	    }
    28	
    29	    /** Soma das noites a preço de tabela (com alta temporada), cada noite arredondada. */
    30	    public BigDecimal seasonalSubtotal() {
    31	        BigDecimal sum = Money.ZERO;
    32	        for (LocalDate d = checkIn; d.isBefore(checkOut); d = d.plusDays(1)) {
    33	            sum = sum.add(nightPrice(d));
    34	        }
    35	        return sum;
    36	    }
    37	}
