     1	package br.com.marealta;
     2	
     3	import com.zaxxer.hikari.HikariConfig;
     4	import com.zaxxer.hikari.HikariDataSource;
     5	
     6	import java.sql.Connection;
     7	import java.sql.PreparedStatement;
     8	import java.sql.SQLException;
     9	import java.sql.Statement;
    10	
    11	/** Pool de conexões, criação do esquema e transações. */
    12	public final class Db {
    13	    @FunctionalInterface
    14	    public interface TxWork<T> { T run(Connection c) throws SQLException; }
    15	
    16	    private final HikariDataSource ds;
    17	
    18	    public Db(String url, String user, String password) {
    19	        HikariConfig cfg = new HikariConfig();
    20	        cfg.setJdbcUrl(url);
    21	        cfg.setUsername(user);
    22	        cfg.setPassword(password);
    23	        cfg.setMaximumPoolSize(10);
    24	        cfg.setInitializationFailTimeout(-1);
    25	        this.ds = new HikariDataSource(cfg);
    26	    }
    27	
    28	    public <T> T tx(TxWork<T> work) {
    29	        try (Connection c = ds.getConnection()) {
    30	            c.setAutoCommit(false);
    31	            try {
    32	                T result = work.run(c);
    33	                c.commit();
    34	                return result;
    35	            } catch (Throwable t) {
    36	                c.rollback();
    37	                throw t;
    38	            }
    39	        } catch (SQLException e) {
    40	            throw new IllegalStateException("Erro de banco de dados", e);
    41	        }
    42	    }
    43	
    44	    /** Espera o banco aceitar conexões, cria as tabelas e cadastra os quartos. */
    45	    public void init() {
    46	        SQLException last = null;
    47	        for (int i = 0; i < 60; i++) {
    48	            try (Connection c = ds.getConnection()) {
    49	                migrate(c);
    50	                return;
    51	            } catch (SQLException e) {
    52	                last = e;
    53	                try { Thread.sleep(1000); } catch (InterruptedException ie) { Thread.currentThread().interrupt(); break; }
    54	            }
    55	        }
    56	        throw new IllegalStateException("Banco de dados indisponível", last);
    57	    }
    58	
    59	    private void migrate(Connection c) throws SQLException {
    60	        c.setAutoCommit(false);
    61	        try (Statement s = c.createStatement()) {
    62	            // evita corrida entre instâncias subindo juntas
    63	            s.execute("SELECT pg_advisory_xact_lock(727401)");
    64	            s.execute("""
    65	                    CREATE TABLE IF NOT EXISTS rooms (
    66	                        number INT PRIMARY KEY,
    67	                        type VARCHAR(20) NOT NULL,
    68	                        capacity INT NOT NULL,
    69	                        nightly_rate NUMERIC(12,2) NOT NULL)""");
    70	            s.execute("""
    71	                    CREATE TABLE IF NOT EXISTS reservations (
    72	                        id BIGSERIAL PRIMARY KEY,
    73	                        room_number INT NOT NULL REFERENCES rooms(number),
    74	                        guest_name TEXT NOT NULL,
    75	                        guest_email TEXT NOT NULL,
    76	                        guest_cpf TEXT NOT NULL,
    77	                        check_in DATE NOT NULL,
    78	                        check_out DATE NOT NULL,
    79	                        guests INT NOT NULL,
    80	                        rate_plan VARCHAR(30) NOT NULL,
    81	                        company_code VARCHAR(60),
    82	                        nights INT NOT NULL,
    83	                        subtotal NUMERIC(12,2) NOT NULL,
    84	                        discount NUMERIC(12,2) NOT NULL,
    85	                        total NUMERIC(12,2) NOT NULL,
    86	                        status VARCHAR(20) NOT NULL,
    87	                        amount_paid NUMERIC(12,2) NOT NULL,
    88	                        refund NUMERIC(12,2))""");
    89	            s.execute("CREATE INDEX IF NOT EXISTS idx_reservations_room ON reservations(room_number, check_in)");
    90	            s.execute("""
    91	                    CREATE TABLE IF NOT EXISTS messages (
    92	                        id BIGSERIAL PRIMARY KEY,
    93	                        channel VARCHAR(20) NOT NULL,
    94	                        recipient TEXT NOT NULL,
    95	                        subject TEXT NOT NULL,
    96	                        body TEXT NOT NULL)""");
    97	        }
    98	        String seed = "INSERT INTO rooms (number, type, capacity, nightly_rate) VALUES (?,?,?,?) ON CONFLICT (number) DO NOTHING";
    99	        try (PreparedStatement ps = c.prepareStatement(seed)) {
   100	            Object[][] rooms = {
   101	                    {101, "STANDARD", 2, "249.90"}, {102, "STANDARD", 2, "249.90"},
   102	                    {201, "DELUXE", 3, "389.90"}, {202, "DELUXE", 3, "389.90"},
   103	                    {301, "SUITE", 4, "579.90"}};
   104	            for (Object[] r : rooms) {
   105	                ps.setInt(1, (Integer) r[0]);
   106	                ps.setString(2, (String) r[1]);
   107	                ps.setInt(3, (Integer) r[2]);
   108	                ps.setBigDecimal(4, new java.math.BigDecimal((String) r[3]));
   109	                ps.addBatch();
   110	            }
   111	            ps.executeBatch();
   112	        }
   113	        c.commit();
   114	    }
   115	}
