    25	    public Optional<Room> room(Connection c, int number, boolean lock) throws SQLException {
    26	        String sql = "SELECT number, type, capacity, nightly_rate FROM rooms WHERE number = ?" + (lock ? " FOR UPDATE" : "");
    27	        try (PreparedStatement ps = c.prepareStatement(sql)) {
    28	            ps.setInt(1, number);
    29	            try (ResultSet rs = ps.executeQuery()) {
    30	                return rs.next() ? Optional.of(room(rs)) : Optional.empty();
    31	            }
    32	        }
    33	    }
