    55	                        + "company_code, nights, subtotal, discount, total, status, amount_paid) VALUES (?,?,?,?,?,?,?,?,?,?,?,?,?,?,?) "
    56	                        + "RETURNING " + RES_COLS)) {
    57	            int i = 1;
    58	            ps.setInt(i++, r.roomNumber());
    59	            ps.setString(i++, r.guestName());
    60	            ps.setString(i++, r.guestEmail());
    61	            ps.setString(i++, r.guestCpf());
    62	            ps.setObject(i++, r.checkIn());
