    66	            ps.setString(i++, r.companyCode());
    67	            ps.setInt(i++, r.nights());
    68	            ps.setBigDecimal(i++, r.subtotal());
    69	            ps.setBigDecimal(i++, r.discount());
    70	            ps.setBigDecimal(i++, r.total());
    71	            ps.setString(i++, r.status().name());
    72	            ps.setBigDecimal(i, r.amountPaid());
    73	            try (ResultSet rs = ps.executeQuery()) {
