    90	    public Reservation update(Connection c, long id, ReservationStatus status, BigDecimal amountPaid, BigDecimal refund) throws SQLException {
    91	        try (PreparedStatement ps = c.prepareStatement(
    92	                "UPDATE reservations SET status = ?, amount_paid = ?, refund = ? WHERE id = ? RETURNING " + RES_COLS)) {
    93	            ps.setString(1, status.name());
    94	            ps.setBigDecimal(2, amountPaid);
    95	            ps.setBigDecimal(3, refund);
    96	            ps.setLong(4, id);
    97	            try (ResultSet rs = ps.executeQuery()) {
    98	                rs.next();
    99	                return reservation(rs);
   100	            }
   101	        }
   102	    }
