   104	    /** Reservas pagas (confirmada, check-in, check-out) que ocupam o quarto na noite indicada. */
   105	    public List<Reservation> occupying(Connection c, LocalDate night) throws SQLException {
   106	        return list(c, "SELECT " + RES_COLS + " FROM reservations WHERE status IN ('CONFIRMED','CHECKED_IN','CHECKED_OUT') "
   107	                + "AND check_in <= ? AND ? < check_out ORDER BY room_number, id", night, night);
