   110	    /** Reservas que começam no período [from, to) e ainda têm dinheiro com a pousada. */
   111	    public List<Reservation> revenue(Connection c, LocalDate from, LocalDate to) throws SQLException {
   112	        return list(c, "SELECT " + RES_COLS + " FROM reservations WHERE check_in >= ? AND check_in < ? "
