     1	package br.com.marealta;
     2	
     3	import br.com.marealta.plan.PricingContext;
     4	import br.com.marealta.plan.Quote;
     5	import br.com.marealta.plan.RatePlan;
     6	import br.com.marealta.plan.RatePlans;
     7	
     8	import java.math.BigDecimal;
     9	import java.sql.Connection;
    10	import java.sql.SQLException;
    11	import java.time.LocalDate;
    12	import java.util.List;
    13	
    14	public final class ReservationService {
    15	    public record CreateCommand(int roomNumber, String guestName, String guestEmail, String guestCpf,
    16	                                LocalDate checkIn, LocalDate checkOut, int guests, String ratePlan, String companyCode) {}
    17	
    18	    /** Reserva junto com o quarto, para montar respostas e comprovantes. */
    19	    public record Booking(Reservation reservation, Room room) {}
    20	
    21	    private final Db db;
    22	    private final Repository repo;
    23	
    24	    public ReservationService(Db db, Repository repo) {
    25	        this.db = db;
    26	        this.repo = repo;
    27	    }
    28	
    29	    public List<Room> rooms() {
    30	        return db.tx(repo::rooms);
    31	    }
    32	
    33	    public List<Message> messages() {
    34	        return db.tx(repo::messages);
    35	    }
    36	
    37	    public Reservation create(CreateCommand cmd) {
    38	        return db.tx(c -> {
    39	            // O lock do quarto serializa reservas concorrentes para o mesmo quarto.
    40	            Room room = repo.room(c, cmd.roomNumber(), true)
    41	                    .orElseThrow(() -> ApiException.roomNotFound("Quarto " + cmd.roomNumber() + " não existe."));
    42	            if (cmd.guests() > room.capacity()) {
    43	                throw ApiException.capacityExceeded("O quarto " + room.number() + " comporta no máximo " + room.capacity() + " hóspedes.");
    44	            }
    45	            RatePlan plan = RatePlans.find(cmd.ratePlan())
    46	                    .orElseThrow(() -> ApiException.invalid("ratePlan desconhecido: " + cmd.ratePlan()));
    47	            PricingContext ctx = new PricingContext(room, cmd.checkIn(), cmd.checkOut(), cmd.companyCode());
    48	            Quote quote = plan.quote(ctx);
    49	            if (repo.hasOverlap(c, room.number(), cmd.checkIn(), cmd.checkOut())) {
    50	                throw ApiException.roomUnavailable("O quarto " + room.number() + " já está reservado em alguma das noites.");
    51	            }
    52	            boolean corporate = "CORPORATE".equals(plan.code());
    53	            Reservation draft = new Reservation(0, room.number(), cmd.guestName(), cmd.guestEmail(), cmd.guestCpf(),
    54	                    cmd.checkIn(), cmd.checkOut(), cmd.guests(), plan.code(), corporate ? cmd.companyCode().trim() : null,
    55	                    ctx.nights(), quote.subtotal(), quote.discount(), quote.total(),
    56	                    ReservationStatus.PENDING, Money.ZERO, null);
    57	            return repo.insert(c, draft);
    58	        });
    59	    }
    60	
    61	    public Reservation get(long id) {
    62	        return db.tx(c -> load(c, id, false));
    63	    }
    64	
    65	    public Reservation confirm(long id) {
    66	        return db.tx(c -> {
    67	            Reservation r = load(c, id, true);
    68	            require(r.status() == ReservationStatus.PENDING, "Só é possível confirmar uma reserva pendente.");
    69	            Reservation updated = repo.update(c, id, ReservationStatus.CONFIRMED, r.total(), r.refund());
    70	            Room room = repo.room(c, r.roomNumber(), false).orElseThrow();
    71	            repo.insertMessage(c, new Message(0, "EMAIL", updated.guestEmail(), Receipt.CONFIRMATION_SUBJECT,
    72	                    Receipt.confirmationEmail(updated, room)));
    73	            return updated;
    74	        });
    75	    }
    76	
    77	    public Reservation cancel(long id) {
    78	        return db.tx(c -> {
    79	            Reservation r = load(c, id, true);
    80	            require(r.status() == ReservationStatus.PENDING || r.status() == ReservationStatus.CONFIRMED,
    81	                    "Só é possível cancelar uma reserva pendente ou confirmada.");
    82	            RatePlan plan = RatePlans.find(r.ratePlan()).orElseThrow();
    83	            BigDecimal refund = Money.round(plan.refund(r.amountPaid()));
    84	            return repo.update(c, id, ReservationStatus.CANCELLED, r.amountPaid(), refund);
    85	        });
    86	    }
    87	
    88	    public Reservation checkIn(long id) {
    89	        return db.tx(c -> {
    90	            Reservation r = load(c, id, true);
    91	            require(r.status() == ReservationStatus.CONFIRMED, "Só é possível fazer check-in de uma reserva confirmada.");
    92	            return repo.update(c, id, ReservationStatus.CHECKED_IN, r.amountPaid(), r.refund());
    93	        });
    94	    }
    95	
    96	    public Booking checkOut(long id) {
    97	        return db.tx(c -> {
    98	            Reservation r = load(c, id, true);
    99	            require(r.status() == ReservationStatus.CHECKED_IN, "Só é possível fazer check-out de quem fez check-in.");
   100	            Reservation updated = repo.update(c, id, ReservationStatus.CHECKED_OUT, r.amountPaid(), r.refund());
   101	            return new Booking(updated, repo.room(c, r.roomNumber(), false).orElseThrow());
   102	        });
   103	    }
   104	
   105	    /** Segunda via do comprovante: só para reserva paga. */
   106	    public Booking document(long id) {
