    47	            PricingContext ctx = new PricingContext(room, cmd.checkIn(), cmd.checkOut(), cmd.companyCode());
    48	            Quote quote = plan.quote(ctx);
    49	            if (repo.hasOverlap(c, room.number(), cmd.checkIn(), cmd.checkOut())) {
    50	                throw ApiException.roomUnavailable("O quarto " + room.number() + " já está reservado em alguma das noites.");
    51	            }
