    53	            Reservation draft = new Reservation(0, room.number(), cmd.guestName(), cmd.guestEmail(), cmd.guestCpf(),
    54	                    cmd.checkIn(), cmd.checkOut(), cmd.guests(), plan.code(), corporate ? cmd.companyCode().trim() : null,
    55	                    ctx.nights(), quote.subtotal(), quote.discount(), quote.total(),
    56	                    ReservationStatus.PENDING, Money.ZERO, null);
