 9	import static org.junit.jupiter.api.Assertions.*;
10	
11	class PlansTest {
12	    static final Room STANDARD = new Room(101, RoomType.STANDARD, 2, Money.of("249.90"));
13	    static final Room DELUXE = new Room(201, RoomType.DELUXE, 3, Money.of("389.90"));
14	
15	    static Quote quote(String plan, Room room, String in, String out, String company) {
16	        return RatePlans.find(plan).orElseThrow()
17	                .quote(new PricingContext(room, LocalDate.parse(in), LocalDate.parse(out), company));
18	    }
19	
20	    @Test void highSeasonStandard() {
21	        Quote q = quote("STANDARD", STANDARD, "2027-07-10", "2027-07-12", null);
22	        assertEquals(Money.of("599.76"), q.total());
23	    }
24	
25	    @Test void seasonBoundaries() {
26	        assertFalse(PricingContext.isHighSeason(LocalDate.parse("2027-12-14")));
27	        assertTrue(PricingContext.isHighSeason(LocalDate.parse("2027-12-15")));
28	        assertTrue(PricingContext.isHighSeason(LocalDate.parse("2028-02-29")));
29	        assertFalse(PricingContext.isHighSeason(LocalDate.parse("2027-03-01")));
30	    }
31	
32	    @Test void nonRefundable() {
33	        Quote q = quote("NON_REFUNDABLE", DELUXE, "2027-03-10", "2027-03-12", null);
34	        assertEquals(Money.of("779.80"), q.subtotal());
35	        assertEquals(Money.of("116.97"), q.discount());
36	        assertEquals(Money.ZERO, RatePlans.find("NON_REFUNDABLE").orElseThrow().refund(q.total()));
37	    }
38	
39	    @Test void corporate() {
40	        Quote q = quote("CORPORATE", DELUXE, "2027-03-10", "2027-03-12", "TECNOSUL");
41	        assertEquals(Money.of("93.58"), q.discount());
42	        assertEquals(Money.of("686.22"), q.total());
43	        assertThrows(ApiException.class, () -> quote("CORPORATE", DELUXE, "2027-03-10", "2027-03-12", null));
44	        assertThrows(ApiException.class, () -> quote("CORPORATE", DELUXE, "2027-03-10", "2027-03-12", "OUTRA"));
45	    }
46	
47	    @Test void weekendPackage() {
48	        Quote q = quote("WEEKEND_PACKAGE", DELUXE, "2027-03-12", "2027-03-14", null);
49	        assertEquals(Money.of("820.00"), q.total());
50	        assertEquals(Money.ZERO, q.discount());
51	        assertEquals(Money.of("410.00"), RatePlans.find("WEEKEND_PACKAGE").orElseThrow().refund(q.total()));
52	        assertEquals(Money.of("520.00"), quote("WEEKEND_PACKAGE", STANDARD, "2027-07-09", "2027-07-11", null).total());
53	        assertThrows(ApiException.class, () -> quote("WEEKEND_PACKAGE", DELUXE, "2027-03-13", "2027-03-15", null));
54	        assertThrows(ApiException.class, () -> quote("WEEKEND_PACKAGE", DELUXE, "2027-03-12", "2027-03-15", null));
55	    }
56	
57	    @Test void longStay() {
58	        Quote q = quote("LONG_STAY", STANDARD, "2027-03-01", "2027-03-08", null);
59	        assertEquals(Money.of("1749.30"), q.subtotal());
60	        assertEquals(Money.of("174.93"), q.discount());
61	        assertEquals(Money.of("1574.37"), q.total());
62	        assertThrows(ApiException.class, () -> quote("LONG_STAY", STANDARD, "2027-03-01", "2027-03-07", null));
63	    }
64	
65	    @Test void halfEvenRounding() {
66	        assertEquals(Money.of("0.12"), Money.times(new BigDecimal("0.25"), new BigDecimal("0.5")));
67	    }
68	
69	    @Test void receipt() {
70	        Reservation r = new Reservation(7, 201, "Carla Dias", "c@x.com", "111.222.333-44", LocalDate.parse("2027-03-10"),
71	                LocalDate.parse("2027-03-12"), 2, "STANDARD", null, 2, Money.of("779.80"), Money.ZERO, Money.of("779.80"),
72	                ReservationStatus.CONFIRMED, Money.of("779.80"), null);
73	        assertEquals("""
74	                Comprovante de reserva nº 7
75	                Hóspede: Carla Dias (CPF 111.222.333-44)
76	                Quarto: 201 (DELUXE)
77	                Entrada: 10/03/2027 | Saída: 12/03/2027 | 2 diárias
78	                Diárias: R$ 779,80
79	                Total: R$ 779,80""", Receipt.text(r, DELUXE));
80	        assertEquals("R$ 1.234,56", Money.brl(Money.of("1234.56")));
81	    }
82	}

